-- lazy.nvim specification (point `dir` to your local clone of apps/neovim)
{
  "Real-Fruit-Snacks/rfs-themes",
  name = "cyclorama-dawn",
  priority = 1000,
  config = function(plugin)
    vim.opt.rtp:append(plugin.dir .. "/apps/neovim")
    require("cyclorama").setup({
      variant = "cyclorama-dawn",
      transparent = false,
      italic_comments = true,
      terminal_colors = true,
    })
    vim.cmd.colorscheme("cyclorama-dawn")
  end,
}

